import{_ as r,a0 as p,w as o,s as d,I as n,x as t,a1 as i,A as a,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何在 Ubuntu 和其他 Linux 發行版中啓動、停止和重啓服務 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 和其他 Linux 發行版中啓動、停止和重啓服務 | LCTT (201912) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 和其他 Linux 發行版中啓動、停止和重啓服務 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 和其他 Linux 發行版中啓動、停止和重啓服務 | LCTT (201912) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201912/20191220 How to Start, Stop - Restart Services in Ubuntu and Other Linux Distributions","title":"如何在 Ubuntu 和其他 Linux 發行版中啓動、停止和重啓服務","tag":"201912","desc":""},"relativePath":"201912/20191220 How to Start, Stop - Restart Services in Ubuntu and Other Linux Distributions.md","filePath":"[post].md"}'),u={name:"201912/20191220 How to Start, Stop - Restart Services in Ubuntu and Other Linux Distributions.md"};function h(g,s,b,c,k,m){const e=p("Link");return o(),d("div",null,[s[23]||(s[23]=n("h1",{id:"如何在-ubuntu-和其他-linux-發行版中啓動、停止和重啓服務",tabindex:"-1"},[t("如何在 Ubuntu 和其他 Linux 發行版中啓動、停止和重啓服務 "),n("a",{class:"header-anchor",href:"#如何在-ubuntu-和其他-linux-發行版中啓動、停止和重啓服務","aria-label":"Permalink to “如何在 Ubuntu 和其他 Linux 發行版中啓動、停止和重啓服務”"},"​")],-1)),s[24]||(s[24]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/201912/28/081645vee5lkult55kituu.jpg",alt:""})],-1)),n("p",null,[s[2]||(s[2]=t("服務是必不可少的後台進程，它通常隨系統啓動，並在關機時關閉。如果你是系統管理員，那麼你會定期處理服務。如果你是普通桌面用户，你可能會遇到需要重啓服務的情況，例如",-1)),i(e,{href:"https://itsfoss.com/keyboard-mouse-sharing-between-computers/"},{default:a(()=>[...s[0]||(s[0]=[t("安裝 Barrier 來用於在計算機之間共享鼠標和鍵盤",-1)])]),_:1}),s[3]||(s[3]=t("。或",-1)),i(e,{href:"https://itsfoss.com/set-up-firewall-gufw/"},{default:a(()=>[...s[1]||(s[1]=[t("在使用 ufw 設置防火牆",-1)])]),_:1}),s[4]||(s[4]=t("時。",-1))]),s[25]||(s[25]=l('<p>今天，我將向你展示兩種管理服務的方式。你將學習在 Ubuntu 或任何其他 Linux 發行版中啓動、停止和重啓服務。</p><blockquote><p>systemd 與 init</p><p>如今，Ubuntu 和許多其他發行版都使用 systemd 而不是舊的 init。</p><p>在 systemd 中，可以使用 <code>systemctl</code> 命令管理服務。</p><p>在 init 中，你可以使用 <code>service</code> 命令管理服務。</p><p>你會注意到，即使你的 Linux 系統使用 systemd，它仍然可以使用 <code>service</code> 命令（與 init 系統一起使用的）。這是因為 <code>service</code> 命令實際上已重定向到 <code>systemctl</code>。systemd 引入了向後兼容性，因為系統管理員們習慣使用 <code>service</code> 命令。</p><p>在本教程中，我將同時展示 <code>systemctl</code> 和 <code>service</code> 命令。</p></blockquote><p>我用的是 Ubuntu 18.04，但其他版本的過程也一樣。</p><h3 id="方法-1-使用-systemd-在-linux-中管理服務" tabindex="-1">方法 1：使用 systemd 在 Linux 中管理服務 <a class="header-anchor" href="#方法-1-使用-systemd-在-linux-中管理服務" aria-label="Permalink to “方法 1：使用 systemd 在 Linux 中管理服務”">​</a></h3><p>我從 systemd 開始，因為它被廣泛接受。</p><h4 id="_1、列出所有服務" tabindex="-1">1、列出所有服務 <a class="header-anchor" href="#_1、列出所有服務" aria-label="Permalink to “1、列出所有服務”">​</a></h4><p>為了管理服務，你首先需要知道系統上有哪些服務可用。你可以使用 systemd 的命令列出 Linux 系統上的所有服務：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl list-unit-files --type service -all</span></span></code></pre></div><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2019/12/systemctl_list_services.png?ssl=1" alt="systemctl list-unit-files"></p><p>此命令將輸出所有服務的狀態。服務狀態有<ruby>啓用<rt>enabled</rt></ruby>、<ruby>禁用<rt>disabled</rt></ruby>、<ruby>屏蔽<rt>masked</rt></ruby>（在取消屏蔽之前處於非活動狀態）、<ruby>靜態<rt>static</rt></ruby>和<ruby>已生成<rt>generated</rt></ruby>。</p>',10)),n("p",null,[s[6]||(s[6]=t("與 ",-1)),i(e,{href:"https://linuxhandbook.com/grep-command-examples/"},{default:a(()=>[...s[5]||(s[5]=[t("grep 命令",-1)])]),_:1}),s[7]||(s[7]=t(" 結合，你可以僅顯示正在運行的服務：",-1))]),s[26]||(s[26]=l('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl | grep running</span></span></code></pre></div><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2019/12/systemctl_grep_running.jpg?ssl=1" alt="Display running services systemctl"></p><p>現在，你知道了如何引用所有不同的服務，你可以開始主動管理它們。</p><p><strong>注意：</strong> 下列命令中的 <code>&lt;service-name&gt;</code> 應該用你想管理的服務名代替。（比如：network-manager、ufw 等）</p><h4 id="_2、啓動服務" tabindex="-1">2、啓動服務 <a class="header-anchor" href="#_2、啓動服務" aria-label="Permalink to “2、啓動服務”">​</a></h4><p>要在 Linux 中啓動服務，你只需使用它的名字：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl start &lt;service-name&gt;</span></span></code></pre></div><h4 id="_3、停止服務" tabindex="-1">3、停止服務 <a class="header-anchor" href="#_3、停止服務" aria-label="Permalink to “3、停止服務”">​</a></h4><p>要停止 systemd 服務，可以使用 <code>systemctl</code> 命令的 <code>stop</code> 選項：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl stop &lt;service-name&gt;</span></span></code></pre></div><h4 id="_4、重啓服務" tabindex="-1">4、重啓服務 <a class="header-anchor" href="#_4、重啓服務" aria-label="Permalink to “4、重啓服務”">​</a></h4><p>要重啓 systemd 服務，可以使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl restart &lt;service-name&gt;</span></span></code></pre></div><h4 id="_5、檢查服務狀態" tabindex="-1">5、檢查服務狀態 <a class="header-anchor" href="#_5、檢查服務狀態" aria-label="Permalink to “5、檢查服務狀態”">​</a></h4><p>你可以通過打印服務狀態來確認你已經成功執行特定操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl status &lt;service-name&gt;</span></span></code></pre></div><p>這將以以下方式輸出：</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/12/systemctl_status.jpg?ssl=1" alt="systemctl status"></p><p>這是 systemd 的內容。現在切換到 init。</p><h3 id="方法-2-使用-init-在-linux-中管理服務" tabindex="-1">方法 2：使用 init 在 Linux 中管理服務 <a class="header-anchor" href="#方法-2-使用-init-在-linux-中管理服務" aria-label="Permalink to “方法 2：使用 init 在 Linux 中管理服務”">​</a></h3><p>init 的命令和 systemd 的一樣簡單。</p><h4 id="_1、列出所有服務-1" tabindex="-1">1、列出所有服務 <a class="header-anchor" href="#_1、列出所有服務-1" aria-label="Permalink to “1、列出所有服務”">​</a></h4><p>要列出所有 Linux 服務，使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>service --status-all</span></span></code></pre></div><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2019/12/service_status_all.png?ssl=1" alt="service –status-all"></p><p>前面的 <code>[ – ]</code> 代表<strong>禁用</strong>，<code>[ + ]</code> 代表<strong>啓用</strong>。</p><h4 id="_2、啓動服務-1" tabindex="-1">2、啓動服務 <a class="header-anchor" href="#_2、啓動服務-1" aria-label="Permalink to “2、啓動服務”">​</a></h4><p>要在 Ubuntu 和其他發行版中啓動服務，使用命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>service &lt;service-name&gt; start</span></span></code></pre></div><h4 id="_3、停止服務-1" tabindex="-1">3、停止服務 <a class="header-anchor" href="#_3、停止服務-1" aria-label="Permalink to “3、停止服務”">​</a></h4><p>停止服務同樣簡單。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>service &lt;service-name&gt; stop</span></span></code></pre></div><h4 id="_4、重啓服務-1" tabindex="-1">4、重啓服務 <a class="header-anchor" href="#_4、重啓服務-1" aria-label="Permalink to “4、重啓服務”">​</a></h4><p>如果你想重啓服務，命令是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>service &lt;service-name&gt; restart</span></span></code></pre></div><h4 id="_5、檢查服務狀態-1" tabindex="-1">5、檢查服務狀態 <a class="header-anchor" href="#_5、檢查服務狀態-1" aria-label="Permalink to “5、檢查服務狀態”">​</a></h4><p>此外，要檢查是否達到了預期的結果，你可以輸出服務狀態：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>service &lt;service-name&gt; status</span></span></code></pre></div><p>這將以以下方式輸出：</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2019/12/service_status.jpg?ssl=1" alt="service status"></p><p>最重要的是，這將告訴你某項服務是否處於活躍狀態（正在運行）。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>今天，我詳細介紹了兩種在 Ubuntu 或任何其他 Linux 系統上管理服務的非常簡單的方法。 希望本文對你有所幫助。</p><p>你更喜歡哪種方法？ 讓我在下面的評論中知道！</p><hr>',45)),n("p",null,[s[9]||(s[9]=t("via: ",-1)),i(e,{href:"https://itsfoss.com/start-stop-restart-services-linux/"},{default:a(()=>[...s[8]||(s[8]=[t("https://itsfoss.com/start-stop-restart-services-linux/",-1)])]),_:1})]),n("p",null,[s[14]||(s[14]=t("作者：",-1)),i(e,{href:"https://itsfoss.com/author/sergiu/"},{default:a(()=>[...s[10]||(s[10]=[t("Sergiu",-1)])]),_:1}),s[15]||(s[15]=t(" 選題：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:a(()=>[...s[11]||(s[11]=[t("lujun9972",-1)])]),_:1}),s[16]||(s[16]=t(" 譯者：",-1)),i(e,{href:"https://github.com/geekpi"},{default:a(()=>[...s[12]||(s[12]=[t("geekpi",-1)])]),_:1}),s[17]||(s[17]=t(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:a(()=>[...s[13]||(s[13]=[t("wxy",-1)])]),_:1})]),n("p",null,[s[20]||(s[20]=t("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...s[18]||(s[18]=[t("LCTT",-1)])]),_:1}),s[21]||(s[21]=t(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:a(()=>[...s[19]||(s[19]=[t("Linux中國",-1)])]),_:1}),s[22]||(s[22]=t(" 榮譽推出",-1))])])}const v=r(u,[["render",h]]);export{x as __pageData,v as default};
